# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#065f46" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İNANÇ BAKIMINDAN İNSANLAR I: MÜMİN VE MÜNAFIK KAVRAMLARI</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="28" fill="#059669" rx="6"/>\n  <text x="177" y="73" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">1. MÜMİN (KALP İLE TASDİK + DİL İLE İKRAR)</text>\n  <text x="25" y="96" fill="#064e3b" font-size="9.5" font-weight="bold">• Sözlük ve Terim Anlamı:</text>\n  <text x="29" y="110" fill="#1e293b" font-size="9">"Güven veren, emin kılan, tasdik eden" demektir.</text>\n  <text x="29" y="123" fill="#1e293b" font-size="9">Allah\'a, Hz. Peygamber\'e ve iman esaslarının</text>\n  <text x="29" y="136" fill="#1e293b" font-size="9">tamamına kalbiyle inanıp diliyle ikrar eden kişidir.</text>\n  <text x="25" y="154" fill="#064e3b" font-size="9.5" font-weight="bold">• Enfal Suresi 2-4. Ayetlerde Özellikleri:</text>\n  <text x="29" y="168" fill="#1e293b" font-size="9">1) Allah anıldığında kalpleri titrer (saygı/haşyet).</text>\n  <text x="29" y="182" fill="#1e293b" font-size="9">2) Allah\'ın ayetleri okunduğunda imanları artar.</text>\n  <text x="29" y="196" fill="#1e293b" font-size="9">3) Yalnızca Rablerine tevekkül ederler.</text>\n  <text x="29" y="210" fill="#1e293b" font-size="9">4) Namazı dosdoğru kılar ve rızıktan infak ederler.</text>\n  <text x="29" y="228" fill="#047857" font-size="9" font-weight="bold">"İşte onlar gerçek müminlerdir!" (Enfal, 4)</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#fff7ed" stroke="#f97316" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="28" fill="#ea580c" rx="6"/>\n  <text x="522" y="73" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">2. MÜNAFIK (KALPTE İNKÂR + DİLDE İKRAR)</text>\n  <text x="370" y="96" fill="#7c2d12" font-size="9.5" font-weight="bold">• Sözlük ve Terim Anlamı:</text>\n  <text x="374" y="110" fill="#1e293b" font-size="9">"İkiyüzlü, ara bozan, nifak çıkaran" demektir.</text>\n  <text x="374" y="123" fill="#1e293b" font-size="9">Kalbiyle inanmadığı hâlde çıkar sağlamak veya</text>\n  <text x="374" y="136" fill="#1e293b" font-size="9">zarar vermek için diliyle Müslüman görünendir.</text>\n  <text x="370" y="154" fill="#7c2d12" font-size="9.5" font-weight="bold">• Kur\'an\'da ve Hadiste Münafıklık:</text>\n  <text x="374" y="168" fill="#1e293b" font-size="9">Kötülüğü emredip iyilikten alıkoyarlar (Tevbe, 67).</text>\n  <text x="370" y="185" fill="#c2410c" font-size="9.5" font-weight="bold">• Amelî Münafıklığın 3 Alameti (Buhari, İman, 24):</text>\n  <text x="374" y="200" fill="#1e293b" font-size="9">1) Konuştuğunda <tspan font-weight="bold" fill="#b91c1c">yalan söylemek</tspan>,</text>\n  <text x="374" y="214" fill="#1e293b" font-size="9">2) Kendisine verilen <tspan font-weight="bold" fill="#b91c1c">emanete ihanet etmek</tspan>,</text>\n  <text x="374" y="228" fill="#1e293b" font-size="9">3) Söz verdiğinde <tspan font-weight="bold" fill="#b91c1c">sözünde durmamak</tspan>.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#991b1b" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İNANÇ BAKIMINDAN İNSANLAR II: KÂFİR VE MÜŞRİK KAVRAMLARI</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="28" fill="#dc2626" rx="6"/>\n  <text x="177" y="73" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">3. KÂFİR (KÜFÜR VE İNKÂR EDEN)</text>\n  <text x="25" y="96" fill="#7f1d1d" font-size="9.5" font-weight="bold">• Sözlük Anlamı (Küfür Kökü):</text>\n  <text x="29" y="110" fill="#1e293b" font-size="9">"Örten, gizleyen, nankörlük eden, inkâr eden".</text>\n  <text x="25" y="128" fill="#7f1d1d" font-size="9.5" font-weight="bold">• Terim Anlamı:</text>\n  <text x="29" y="142" fill="#1e293b" font-size="9">Allah\'ın varlığını ve birliğini veya Hz. Peygamber\'in</text>\n  <text x="29" y="155" fill="#1e293b" font-size="9">getirdiği kesin dinî hükümlerden (zarûrât-ı</text>\n  <text x="29" y="168" fill="#1e293b" font-size="9">dîniyye) birini ya da tamamını inkâr eden,</text>\n  <text x="29" y="181" fill="#1e293b" font-size="9">ilahi emir ve yasaklarla alay eden kimsedir.</text>\n  <text x="25" y="200" fill="#7f1d1d" font-size="9.5" font-weight="bold">• Kur\'an\'daki Hükmü (Muhammed, 34):</text>\n  <text x="29" y="214" fill="#1e293b" font-size="9">İnkâr edip küfür üzere ölenlerin amelleri</text>\n  <text x="29" y="227" fill="#1e293b" font-size="9">boşa gider ve Allah onları bağışlamaz.</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#fdf4ff" stroke="#d946ef" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="28" fill="#a21caf" rx="6"/>\n  <text x="522" y="73" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">4. MÜŞRİK (ALLAH\'A ORTAK KOŞAN)</text>\n  <text x="370" y="96" fill="#701a75" font-size="9.5" font-weight="bold">• Şirk ve Müşrik Tanımı:</text>\n  <text x="374" y="110" fill="#1e293b" font-size="9"><tspan font-weight="bold">Şirk:</tspan> Allah\'ın zatında, sıfatlarında, fiillerinde</text>\n  <text x="374" y="123" fill="#1e293b" font-size="9">veya ulûhiyetinde O\'na ortak koşmaktır.</text>\n  <text x="374" y="137" fill="#1e293b" font-size="9"><tspan font-weight="bold">Müşrik:</tspan> Allah\'a inanmakla birlikte başka</text>\n  <text x="374" y="150" fill="#1e293b" font-size="9">varlıkları da ilah, yardımcı veya şefaatçi</text>\n  <text x="374" y="163" fill="#1e293b" font-size="9">kabul ederek Allah\'a ortak koşan kimsedir.</text>\n  <text x="370" y="181" fill="#701a75" font-size="9.5" font-weight="bold">• Ayetlerde Şirk:</text>\n  <text x="374" y="195" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Tevbe, 31 (Adîy bin Hâtim):</tspan> Din adamlarını</text>\n  <text x="374" y="208" fill="#1e293b" font-size="9">  helal-haram koyucu rabler edinmek.</text>\n  <text x="374" y="221" fill="#86198f" font-size="9" font-weight="bold">• Nisa, 48: "Allah şirk koşulmasını bağışlamaz."</text>\n  <text x="374" y="234" fill="#86198f" font-size="9" font-weight="bold">• Lokman, 13: "Şüphesiz şirk büyük bir zulümdür."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e293b" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">FASIK KAVRAMI VE İNANÇ BAKIMINDAN İNSANLARIN KARŞILAŞTIRMASI</text>\n\n  <rect x="15" y="54" width="320" height="190" fill="#fefce8" stroke="#eab308" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="320" height="26" fill="#ca8a04" rx="6"/>\n  <text x="175" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">5. FASIK (FISK İŞLEYEN / GÜNAHKÂR)</text>\n  <text x="25" y="94" fill="#713f12" font-size="9.5" font-weight="bold">• Sözlük ve Terim Anlamı:</text>\n  <text x="29" y="108" fill="#1e293b" font-size="9">"Hak yoldan çıkmak, kabuğunu delip dışarı</text>\n  <text x="29" y="121" fill="#1e293b" font-size="9">çıkmak, itaatsizlik etmek" anlamındaki <tspan font-weight="bold">fısk</tspan></text>\n  <text x="29" y="134" fill="#1e293b" font-size="9">kökünden gelir; büyük günah işlemeyi alışkanlık</text>\n  <text x="29" y="147" fill="#1e293b" font-size="9">hâline getiren, Allah\'a itaatten ayrılan kişidir.</text>\n  <text x="25" y="165" fill="#713f12" font-size="9.5" font-weight="bold">• Kur\'an\'da Fısk Sayılan Fiiller:</text>\n  <text x="29" y="179" fill="#1e293b" font-size="9">• Borç ilişkilerinde kâtibe/şahide zarar vermek,</text>\n  <text x="29" y="192" fill="#1e293b" font-size="9">• Müminlerle alay etmek ve kötü lakap takmak,</text>\n  <text x="29" y="205" fill="#1e293b" font-size="9">• Sihir/büyü yapmak, fal oklarıyla kısmet aramak,</text>\n  <text x="29" y="218" fill="#1e293b" font-size="9">• Allah\'tan başkası adına kesilen eti yemek.</text>\n  <text x="29" y="234" fill="#a16207" font-size="8.8" font-weight="bold">"İmandan sonra fasıklık ne kötü bir isimdir!" (Hucurat, 11)</text>\n\n  <rect x="350" y="54" width="335" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="350" y="54" width="335" height="26" fill="#2563eb" rx="6"/>\n  <text x="517" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">ÖZET KARŞILAŞTIRMA TABLOSU</text>\n  <text x="362" y="95" fill="#1e3a8a" font-size="9.5" font-weight="bold">Kavram          Kalp (İnanç)        Dil / Davranış</text>\n  <line x1="360" y1="101" x2="675" y2="101" stroke="#93c5fd" stroke-width="1"/>\n  <text x="362" y="118" fill="#047857" font-size="9.5" font-weight="bold">• Mümin:</text>\n  <text x="445" y="118" fill="#1e293b" font-size="9">Tam Tasdik (+)</text>\n  <text x="545" y="118" fill="#1e293b" font-size="9">İkrar ve Salih Amel (+)</text>\n  <text x="362" y="142" fill="#ea580c" font-size="9.5" font-weight="bold">• Münafık:</text>\n  <text x="445" y="142" fill="#1e293b" font-size="9">İnkâr / Nifak (-)</text>\n  <text x="545" y="142" fill="#1e293b" font-size="9">Yalandan İkrar (+/-)</text>\n  <text x="362" y="166" fill="#dc2626" font-size="9.5" font-weight="bold">• Kâfir:</text>\n  <text x="445" y="166" fill="#1e293b" font-size="9">İnkâr / Ret (-)</text>\n  <text x="545" y="166" fill="#1e293b" font-size="9">Açıkça İnkâr (-)</text>\n  <text x="362" y="190" fill="#a21caf" font-size="9.5" font-weight="bold">• Müşrik:</text>\n  <text x="445" y="190" fill="#1e293b" font-size="9">Ortak Koşma (-)</text>\n  <text x="545" y="190" fill="#1e293b" font-size="9">Şirk Koşma (-)</text>\n  <text x="362" y="214" fill="#ca8a04" font-size="9.5" font-weight="bold">• Fasık:</text>\n  <text x="445" y="214" fill="#1e293b" font-size="9">İtaatsizlik / Günah</text>\n  <text x="545" y="214" fill="#1e293b" font-size="9">Büyük Günah İşleme</text>\n  <text x="362" y="235" fill="#1e3a8a" font-size="8.5">* Ehl-i sünnete göre büyük günah işleyen mümin dinden çıkmaz, günahkâr (fasık) olur.</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
